// #vi-sysdiag-proto step 2. The diagram is a hand-maintained file today, per
// #vi-sysdiag-grain — this only fetches and draws it, the same as any other Mermaid
// consumer. No layout code, per #vi-sysdiag-format:opt0.
//
// #vi-sysdiag-svg adds one more hand-drawn reading of the same nodes and edges, laid out
// and styled by hand once — same "no layout code at request time" rule, just a second
// static file instead of a generated render. A radial second style was tried and rejected
// (#vi-sysdiag-svg:opt1): it doesn't work for this kind of diagram.
let mermaidReady = null
let mermaidLoaded = false
const diagramSvgEl = el('diagram-svg')
const diagramMermaidEl = el('diagram-mermaid')
// #vi-sysdiag-svg:opt1 rejected the radial layout (Style B) — an older localStorage value
// of 'b' would otherwise pick a style with no button and no file left to fetch.
let diagramStyle = ['mermaid', 'a'].includes(localStorage.getItem('werk-diagram-style'))
  ? localStorage.getItem('werk-diagram-style')
  : 'mermaid'

async function mountDiagram() {
  if (diagramStyle === 'mermaid') return mountDiagramMermaid()
  return mountDiagramSvg()
}

async function mountDiagramMermaid() {
  diagramMermaidEl.hidden = false
  diagramSvgEl.hidden = true
  if (mermaidLoaded) return
  mermaidLoaded = true
  try {
    if (!mermaidReady) {
      mermaidReady = import('mermaid').then((m) => {
        m.default.initialize({ startOnLoad: false, theme: 'dark' })
        return m.default
      })
    }
    const [mermaid, res] = await Promise.all([mermaidReady, fetch('/api/diagram')])
    const src = (await res.text()).trim()
    if (!src) {
      diagramMermaidEl.textContent = 'No .werk/diagram.mmd yet.'
      return
    }
    const { svg } = await mermaid.render('sysdiag-svg', src)
    diagramMermaidEl.innerHTML = svg
  } catch (err) {
    mermaidLoaded = false
    diagramMermaidEl.textContent = `Diagram failed to render: ${err.message}`
  }
}

let svgLoaded = false
async function mountDiagramSvg() {
  diagramMermaidEl.hidden = true
  diagramSvgEl.hidden = false
  if (svgLoaded) return
  svgLoaded = true
  diagramSvgEl.src = '/api/diagram-svg'
}

