7	function tokenize(line: string): string[] {
8	  const tokens: string[] = []
9	  const re = /"(?:[^"\\]|\\.)*"|\S+/g
10	  let m: RegExpExecArray | null
11	  while ((m = re.exec(line))) tokens.push(m[0])
12	  return tokens
13	}
14	
15	function unquote(tok: string): string {
16	  if (tok.startsWith('"') && tok.endsWith('"')) {
17	    return tok.slice(1, -1).replace(/\\(.)/g, '$1')
18	  }
19	  throw new Error(`expected a quoted string, got: ${tok}`)
20	}
21	
22	function parseNodeTuples(tokens: string[]): IntentNode[] {
23	  const nodes: IntentNode[] = []
24	  let i = 0
25	  while (i < tokens.length) {
26	    const id = tokens[i++]
27	    if (i >= tokens.length) throw new Error(`node "${id}" has no title`)
28	    const title = unquote(tokens[i++])
29	    let card: string | undefined
30	    let desc: string | undefined
31	    if (i < tokens.length && tokens[i].startsWith('@')) card = tokens[i++].slice(1)
32	    if (i < tokens.length && tokens[i].startsWith('"')) desc = unquote(tokens[i++])
33	    nodes.push({ kind: 'node', id, title, card, desc })
34	  }
35	  return nodes
36	}
37	
38	function parseEdge(tokens: string[]): IntentEdge {
39	  // edge <from> -> <to> : <class> "<label>"
40	  const [kw, from, arrow, to, colon, cls, labelTok] = tokens
41	  if (kw !== 'edge' || arrow !== '->' || colon !== ':') {
42	    throw new Error(`malformed edge line: ${tokens.join(' ')}`)
43	  }
44	  return { from, to, cls, label: labelTok ? unquote(labelTok) : '' }
45	}
46	
47	function indentOf(line: string): number {
48	  const m = line.match(/^ */)
49	  return m![0].length
50	}
51	
52	export function parseIntent(text: string): IntentDoc {
53	  const rawLines = text.split('\n')
54	  const lines: { indent: number; tokens: string[] }[] = []
55	  for (const raw of rawLines) {
56	    const trimmed = raw.trim()
57	    if (!trimmed || trimmed.startsWith('#')) continue
58	    lines.push({ indent: indentOf(raw), tokens: tokenize(raw.trim()) })
59	  }
60	
61	  const root: IntentItem[] = []
62	  const edges: IntentEdge[] = []
63	  const stack: { indent: number; children: IntentItem[] }[] = [{ indent: -1, children: root }]
64	
65	  for (const { indent, tokens } of lines) {
66	    const kw = tokens[0]
67	    if (kw === 'edge') {
68	      edges.push(parseEdge(tokens))
69	      continue
70	    }
71	    while (stack.length > 1 && indent <= stack[stack.length - 1].indent) stack.pop()
72	    const parent = stack[stack.length - 1].children
73	
74	    if (kw === 'group') {
75	      const id = tokens[1]
76	      const title = unquote(tokens[2])
77	      const group: IntentGroup = { kind: 'group', id, title, children: [] }
78	      parent.push(group)
79	      stack.push({ indent, children: group.children })
80	    } else if (kw === 'row') {
81	      const row: IntentRow = { kind: 'row', items: parseNodeTuples(tokens.slice(1)) }
82	      parent.push(row)
83	    } else {
84	      throw new Error(`unknown line: ${tokens.join(' ')}`)
85	    }
86	  }
87	
88	  return { items: root, edges }
89	}
