function findBandLocal(bands, lo, hi) {
  const mid=(lo+hi)/2
  const contained = bands.filter(b=>lo<=b.start+1 && hi>=b.end-1)
  if(!contained.length) return undefined
  return contained.reduce((best,b)=>Math.abs((b.start+b.end)/2-mid)<Math.abs((best.start+best.end)/2-mid)?b:best)
